WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_analysis_reason'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '原因分析', 'kp-sl-analysis-reason', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "综合分析：原因分析"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心心法：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "由表及里，分层剖析。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、与归纳概括原因的区别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "归纳概括题只需要“找词”并罗列。而综合分析里的原因，往往材料给得很隐晦，需要你进行【深度推导】。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、分析维度（万能框架）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "当你在材料里找不到现成的词时，用这把万能钥匙去套："}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "思想层面：意识淡薄、观念落后。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "制度层面：法律空白、机制不健全、标准缺失。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "监管层面：执法不严、多头管理、主体责任缺位。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "利益层面：追求短期经济利益、考核机制扭曲。"}]}]}]}]}$$ AS jsonb), NULL, '原因分析的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "综合分析", "原因分析"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_analysis_reason", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
